import type {SizeHint, Size, Margin} from "./types"
import {Sizeable} from "./types"
import {Layoutable} from "./layoutable"
import type {LRTB} from "../util/bbox"
import {BBox} from "../util/bbox"

export class BorderLayout extends Layoutable {
  override *[Symbol.iterator]() {
    yield this.top_panel
    yield this.bottom_panel
    yield this.left_panel
    yield this.right_panel
    yield this.center_panel
  }

  top_panel: Layoutable
  bottom_panel: Layoutable
  left_panel: Layoutable
  right_panel: Layoutable

  center_panel: Layoutable

  inner_top_panel?: Layoutable
  inner_bottom_panel?: Layoutable
  inner_left_panel?: Layoutable
  inner_right_panel?: Layoutable

  aligns: LRTB<boolean> = {left: true, right: true, top: true, bottom: true}

  min_border: Margin = {left: 0, top: 0, right: 0, bottom: 0}
  padding: Margin = {left: 0, top: 0, right: 0, bottom: 0}

  // Borders imposed by an aligning parent, so that this layout's frame can line
  // up with its neighbours' without its own borders having to shrink.
  align_border: Margin = {left: 0, top: 0, right: 0, bottom: 0}

  center_border_width: number = 0

  protected _measure(viewport: Size): SizeHint {
    viewport = new Sizeable({
      width: this.sizing.width_policy == "fixed" || viewport.width == Infinity ? this.sizing.width : viewport.width,
      height: this.sizing.height_policy == "fixed" || viewport.height == Infinity ? this.sizing.height : viewport.height,
    })

    const left_hint = this.left_panel.measure({width: 0, height: viewport.height})
    const left = Math.max(Math.max(left_hint.width, this.min_border.left) + this.padding.left, this.align_border.left)

    const right_hint = this.right_panel.measure({width: 0, height: viewport.height})
    const right = Math.max(Math.max(right_hint.width, this.min_border.right) + this.padding.right, this.align_border.right)

    const top_hint = this.top_panel.measure({width: viewport.width, height: 0})
    const top = Math.max(top_hint.height, this.min_border.top) + this.padding.top

    const bottom_hint = this.bottom_panel.measure({width: viewport.width, height: 0})
    const bottom = Math.max(Math.max(bottom_hint.height, this.min_border.bottom) + this.padding.bottom, this.align_border.bottom)

    const center_viewport = new Sizeable(viewport).shrink_by({left, right, top, bottom})
    const center = this.center_panel.measure(center_viewport)

    const width = left + center.width + right
    const height = top + center.height + bottom

    const align = (() => {
      const {width_policy, height_policy} = this.center_panel.sizing
      return {
        ...this.aligns,
        fixed_width: width_policy == "fixed",
        fixed_height: height_policy == "fixed",
      }
    })()

    return {width, height, inner: {left, right, top, bottom}, align}
  }

  protected override _set_geometry(outer: BBox, inner: BBox): void {
    super._set_geometry(outer, inner)

    if (this.sizing.visible) {
      this.center_panel.set_geometry(inner)

      const left_hint = this.left_panel.measure({width: 0, height: outer.height})
      const right_hint = this.right_panel.measure({width: 0, height: outer.height})
      const top_hint = this.top_panel.measure({width: outer.width, height: 0})
      const bottom_hint = this.bottom_panel.measure({width: outer.width, height: 0})

      const {left, top, right, bottom} = inner

      this.top_panel.set_geometry(new BBox({left, right, bottom: top, height: top_hint.height}))
      this.bottom_panel.set_geometry(new BBox({left, right, top: bottom, height: bottom_hint.height}))
      this.left_panel.set_geometry(new BBox({top, bottom, right: left, width: left_hint.width}))
      this.right_panel.set_geometry(new BBox({top, bottom, left: right, width: right_hint.width}))

      const adjusted_inner = inner.shrink_by(this.center_border_width)

      if (this.inner_top_panel != null) {
        const {left, right, top, width} = adjusted_inner
        const inner_top_hint = this.inner_top_panel.measure({width, height: 0})
        this.inner_top_panel.set_geometry(new BBox({left, right, top, height: inner_top_hint.height}))
      }

      if (this.inner_bottom_panel != null) {
        const {left, right, bottom, width} = adjusted_inner
        const inner_bottom_hint = this.inner_bottom_panel.measure({width, height: 0})
        this.inner_bottom_panel.set_geometry(new BBox({left, right, bottom, height: inner_bottom_hint.height}))
      }

      if (this.inner_left_panel != null) {
        const {top, bottom, left, height} = adjusted_inner
        const inner_left_hint = this.inner_left_panel.measure({width: 0, height})
        this.inner_left_panel.set_geometry(new BBox({top, bottom, left, width: inner_left_hint.width}))
      }

      if (this.inner_right_panel != null) {
        const {top, bottom, right, height} = adjusted_inner
        const inner_right_hint = this.inner_right_panel.measure({width: 0, height})
        this.inner_right_panel.set_geometry(new BBox({top, bottom, right, width: inner_right_hint.width}))
      }
    } else {
      this.center_panel.set_geometry(new BBox())

      this.top_panel.set_geometry(new BBox())
      this.bottom_panel.set_geometry(new BBox())
      this.left_panel.set_geometry(new BBox())
      this.right_panel.set_geometry(new BBox())

      this.inner_top_panel?.set_geometry(new BBox())
      this.inner_bottom_panel?.set_geometry(new BBox())
      this.inner_left_panel?.set_geometry(new BBox())
      this.inner_right_panel?.set_geometry(new BBox())
    }
  }
}
import type {Size, SizeHint, BoxSizing, SizingPolicy, Percent} from "./types"
import {Sizeable} from "./types"
import type {CoordinateMapper} from "../util/bbox"
import {BBox} from "../util/bbox"
import {isNumber} from "../util/types"
import {assert} from "../util/assert"
import type {TextBox} from "../graphics"

const {abs, min, max, round} = Math

export type ExtBoxSizing = BoxSizing & {
  readonly size: Partial<Size>
}

export abstract class Layoutable {
  *[Symbol.iterator](): Generator<Layoutable, void, undefined> {}

  absolute: boolean = false

  position: {left: number, top: number} = {left: 0, top: 0}

  protected _bbox: BBox = new BBox()
  protected _inner_bbox: BBox = new BBox()

  get bbox(): BBox {
    return this._bbox
  }

  get inner_bbox(): BBox {
    return this._inner_bbox
  }

  private _sizing: ExtBoxSizing | null = null

  get sizing(): ExtBoxSizing {
    assert(this._sizing != null)
    return this._sizing
  }

  private _dirty: boolean = false
  set dirty(dirty: boolean) {
    this._dirty = dirty
  }
  get dirty(): boolean {
    return this._dirty
  }

  get visible(): boolean {
    return this.sizing.visible
  }

  set visible(visible: boolean) {
    if (this.sizing.visible != visible) {
      this.sizing.visible = visible
      this._dirty = true
    }
  }

  set_sizing(sizing: Partial<BoxSizing> = {}): void {
    const width_policy = sizing.width_policy ?? "fit"
    const width = sizing.width
    const min_width = sizing.min_width
    const max_width = sizing.max_width

    const height_policy = sizing.height_policy ?? "fit"
    const height = sizing.height
    const min_height = sizing.min_height
    const max_height = sizing.max_height

    const aspect = sizing.aspect
    const margin = sizing.margin ?? {top: 0, right: 0, bottom: 0, left: 0}
    const visible = sizing.visible ?? true
    const halign = sizing.halign ?? "start"
    const valign = sizing.valign ?? "start"

    this._sizing = {
      width_policy, min_width, width, max_width,
      height_policy, min_height, height, max_height,
      aspect,
      margin,
      visible,
      halign,
      valign,
      size: {width, height},
    }

    this._init()
  }

  protected _init(): void {}

  protected _set_geometry(outer: BBox, inner: BBox): void {
    this._bbox = outer
    this._inner_bbox = inner
  }

  set_geometry(outer: BBox, inner?: BBox): void {
    const {fixup_geometry} = this
    if (fixup_geometry != null) {
      [outer, inner] = fixup_geometry(outer, inner)
    }
    this._set_geometry(outer, inner ?? outer)
    for (const handler of this._handlers) {
      handler(this._bbox, this._inner_bbox)
    }
  }

  fixup_geometry?(outer: BBox, inner?: BBox): [BBox, BBox?]

  private _handlers: ((outer: BBox, inner: BBox) => void)[] = []

  on_resize(handler: (outer: BBox, inner: BBox) => void): void {
    this._handlers.push(handler)
  }

  is_width_expanding(): boolean {
    return this.sizing.width_policy == "max"
  }

  is_height_expanding(): boolean {
    return this.sizing.height_policy == "max"
  }

  apply_aspect(viewport: Size, {width, height}: Size): Size {
    const {aspect} = this.sizing

    if (aspect != null) {
      const {width_policy, height_policy} = this.sizing

      const gt = (width: SizingPolicy, height: SizingPolicy) => {
        const policies = {max: 4, fit: 3, min: 2, fixed: 1}
        return policies[width] > policies[height]
      }

      if (width_policy != "fixed" && height_policy != "fixed") {
        if (width_policy == height_policy) {
          const w_width = width
          const w_height = round(width / aspect)

          const h_width = round(height * aspect)
          const h_height = height

          const w_diff = abs(viewport.width - w_width) + abs(viewport.height - w_height)
          const h_diff = abs(viewport.width - h_width) + abs(viewport.height - h_height)

          if (w_diff <= h_diff) {
            width = w_width
            height = w_height
          } else {
            width = h_width
            height = h_height
          }
        } else if (gt(width_policy, height_policy)) {
          height = round(width/aspect)
        } else {
          width = round(height*aspect)
        }
      } else if (width_policy == "fixed") {
        height = round(width/aspect)
      } else if (height_policy == "fixed") {
        width = round(height*aspect)
      }
    }

    return {width, height}
  }

  protected abstract _measure(viewport: Sizeable): SizeHint

  measure(viewport_size: Size): SizeHint {
    if (this._sizing == null) {
      this.set_sizing()
    }

    if (!this.sizing.visible) {
      return {width: 0, height: 0}
    }

    const exact_width = (width: number) => {
      return this.sizing.width_policy == "fixed" && this.sizing.width != null ? this.sizing.width : width
    }
    const exact_height = (height: number) => {
      return this.sizing.height_policy == "fixed" && this.sizing.height != null ? this.sizing.height : height
    }

    const viewport = new Sizeable(viewport_size)
      .shrink_by(this.sizing.margin)
      .map(exact_width, exact_height)

    const computed = this._measure(viewport)
    const clipped = this.clip_size(computed, viewport)

    const width = exact_width(clipped.width)
    const height = exact_height(clipped.height)

    const size = this.apply_aspect(viewport, {width, height})
    return {...computed, ...size}
  }

  protected _compute(viewport: Partial<Size>): {outer: BBox, inner?: BBox} {
    const size_hint = this.measure({
      width: viewport.width != null && this.is_width_expanding() ? viewport.width : Infinity,
      height: viewport.height != null && this.is_height_expanding() ? viewport.height : Infinity,
    })

    const {width, height} = size_hint
    const {left, top} = this.position
    const outer = new BBox({left, top, width, height})

    let inner: BBox | undefined = undefined

    if (size_hint.inner != null) {
      const {left, top, right, bottom} = size_hint.inner
      inner = new BBox({left, top, right: width - right, bottom: height - bottom})
    }

    return {outer, inner}
  }

  compute(viewport: Partial<Size> = {}): void {
    const {outer, inner} = this._compute(viewport)
    this.set_geometry(outer, inner)
  }

  get xview(): CoordinateMapper {
    return this.bbox.xview
  }

  get yview(): CoordinateMapper {
    return this.bbox.yview
  }

  clip_size(size: Size, viewport: Size): Size {
    function clip(size: number, vsize: number, min_size?: number | Percent, max_size?: number | Percent): number {
      if (min_size == null) {
        min_size = 0
      } else if (!isNumber(min_size)) {
        min_size = round(min_size.percent*vsize)
      }

      if (max_size == null) {
        max_size = Infinity
      } else if (!isNumber(max_size)) {
        max_size = round(max_size.percent*vsize)
      }

      return max(min_size, min(size, max_size))
    }

    return {
      width: clip(size.width, viewport.width, this.sizing.min_width, this.sizing.max_width),
      height: clip(size.height, viewport.height, this.sizing.min_height, this.sizing.max_height),
    }
  }

  has_size_changed(): boolean {
    const {_dirty} = this
    this._dirty = false
    return _dirty
  }
}

export abstract class ContentLayoutable extends Layoutable {

  protected abstract _content_size(): Sizeable

  protected _measure(viewport: Sizeable): SizeHint {
    const content_size = this._content_size()

    const bounds = viewport
      .bounded_to(this.sizing.size)
      .bounded_to(content_size)

    const width = (() => {
      switch (this.sizing.width_policy) {
        case "fixed":
          return this.sizing.width != null ? this.sizing.width : content_size.width
        case "min":
          return content_size.width
        case "fit":
          return bounds.width
        case "max":
          return max(content_size.width, bounds.width)
      }
    })()

    const height = (() => {
      switch (this.sizing.height_policy) {
        case "fixed":
          return this.sizing.height != null ? this.sizing.height : content_size.height
        case "min":
          return content_size.height
        case "fit":
          return bounds.height
        case "max":
          return max(content_size.height, bounds.height)
      }
    })()

    return {width, height}
  }
}

export class ElementLayout extends ContentLayoutable {
  constructor(readonly el: HTMLElement) {
    super()
  }

  _content_size(): Sizeable {
    const {width, height} = this.el.getBoundingClientRect()
    return new Sizeable({width, height})
  }
}

export class TextLayout extends ContentLayoutable {

  constructor(readonly text: TextBox) {
    super()
  }

  _content_size(): Sizeable {
    return new Sizeable(this.text.size())
  }
}

export class FixedLayout extends ContentLayoutable {

  constructor(readonly size: Partial<Size> = {}) {
    super()
  }

  _content_size(): Sizeable {
    return new Sizeable(this.size)
  }
}

