      for (const child of this.children) {
        child.set_geometry(new BBox())
      }
    } else {
      const left = this.absolute ? outer.left : 0
      let top = this.absolute ? outer.top : 0
      const {width} = outer

      for (const child of this.children) {
        const size_hint = child.measure({width: 0, height: 0})
